BEGIN READ ONLY; SELECT c."Slug",l."Id" AS license_id,l."Seats",count(sa."Id") FILTER (WHERE sa."RevokedAt" IS NULL) AS active_assignments,l."Seats"-count(sa."Id") FILTER (WHERE sa."RevokedAt" IS NULL) AS remaining,bool_and(sa."CompanyId"=l."CompanyId" AND e."CompanyId"=l."CompanyId") AS assignment_employee_scoped FROM "SoftwareLicenses" l JOIN "Companies" c ON c."Id"=l."CompanyId" LEFT JOIN "SoftwareLicenseAssignments" sa ON sa."LicenseId"=l."Id" LEFT JOIN "Employees" e ON e."Id"=sa."EmployeeId" WHERE l."Name"='Santa Kabul Yazılımı 20261026' GROUP BY c."Slug",l."Id",l."Seats"; COMMIT;
